{
  "technical_and_design_decisions": [
    "For U1 (Queue/Topic cleanup), use Spring AMQP's RabbitAdmin.getQueueProperties() to check consumer count and decide on cleanup; optionally invoke RabbitMQ REST API via RabbitManagementTemplate if available; make the cleanup optional via '--clean' flag in stream destroy command.",
    "For U2 (Exception notification), tap into Spring Integration error channels; use a global error channel listener that publishes exceptions to a dedicated error stream/module.",
    "For U3 (Security configuration), leverage Spring Security and Spring Boot's auto-configuration; use OAuth2 or basic auth for REST endpoints; configure security credentials via application properties and environment variables; update DSL shell to support secured endpoints; integrate with Admin UI using session-based or token-based authentication.",
    "For U4 (Documentation of placeholder keys), update the official documentation to list all available placeholder keys (e.g., ${xd.stream.name}, ${xd.job.name}, ${xd.container.id}) with examples.",
    "For U5 (MVC-aware HTTP module), create a new HTTP source module based on embedded Tomcat with Spring MVC support; implement full header mapping and content-type negotiation; reuse existing Spring XD module structure.",
    "For U6 (Polling and events), implement client-side polling with configurable interval; on server-side, use Spring's ApplicationEventPublisher to propagate status changes; consider using WebSocket or Server-Sent Events for push notifications to UI.",
    "For U7 (SFTP source), use Spring Integration SFTP adapter; design configuration properties for host, port, credentials, remote directory; implement a test infrastructure using embedded SFTP server (e.g., Apache MINA SSHD).",
    "For U8 (ElasticSearch sink), use Elasticsearch Spring Data or native REST client; handle indexing of data fields; provide configuration for cluster nodes, authentication, index name."
  ],
  "assumptions": [
    "The existing Spring XD (or Spring Cloud Data Flow) codebase is used as the foundation; all development is done in Java 17+.",
    "The developer is familiar with Spring Framework, Spring Integration, RabbitMQ, Elasticsearch, and Spring Security.",
    "All user stories are implemented within the same software increment; no dependencies between stories block parallel work.",
    "Required dependencies (e.g., RabbitMQ, Elasticsearch, SFTP server) are available in the test environment.",
    "The effort estimates assume a single developer working full-time without interruptions.",
    "Testing includes unit tests, integration tests, and manual verification for each story.",
    "Documentation updates are limited to the scope of the user stories (no comprehensive rework)."
  ],
  "activities": [
    {
      "activity_id": "ACT-001",
      "activity_name": "Implement U1: Queue/Topic cleanup on stream destroy",
      "activity_description": "Design and implement optional cleanup of queues/topics when destroying a stream using the '--clean' flag. Use RabbitAdmin to check consumers and conditionally delete. Handle fanout exchanges and data retention scenarios.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-002",
      "activity_name": "Implement U2: Exception notification via error channel",
      "activity_description": "Add error channel support to stream modules so that exceptions are published to a configurable channel; enable user to tap into the error channel for processing failures.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "ACT-003",
      "activity_name": "Implement U3: Security configurations for REST endpoints",
      "activity_description": "Integrate Spring Security to secure all REST API endpoints. Design configuration approach for credentials, handle DSL shell and Admin UI integration. Implement OOTB security using Spring Boot auto-configuration.",
      "most_likely_effort": 60
    },
    {
      "activity_id": "ACT-004",
      "activity_name": "Implement U4: Document available placeholder keys",
      "activity_description": "Research and document all placeholder keys (e.g., ${xd.stream.name}) available to users in stream and job definitions. Update the official documentation accordingly.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-005",
      "activity_name": "Implement U5: OOTB MVC-aware HTTP module with embedded Tomcat",
      "activity_description": "Build a new HTTP source module that embeds Tomcat and supports Spring MVC features (content-type, header mapping). Ensure compatibility with existing HTTP source usage.",
      "most_likely_effort": 50
    },
    {
      "activity_id": "ACT-006",
      "activity_name": "Implement U6: Polling strategy and event propagation for status changes",
      "activity_description": "Develop client-side polling for stream/job status changes. On server-side, implement event propagation (e.g., ApplicationEvent) between containers and admin server. Optionally add WebSocket/SSE support for UI clients.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-007",
      "activity_name": "Implement U7: SFTP source module",
      "activity_description": "Create an SFTP source module using Spring Integration SFTP adapter. Include configuration for connection parameters and file polling. Set up test infrastructure with embedded SFTP server.",
      "most_likely_effort": 35
    },
    {
      "activity_id": "ACT-008",
      "activity_name": "Implement U8: ElasticSearch sink module",
      "activity_description": "Develop an ElasticSearch sink module that indexes data in real-time. Use Spring Data Elasticsearch or native client. Provide configuration for cluster nodes and index settings.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "ACT-009",
      "activity_name": "Integration testing and cross-story verification",
      "activity_description": "Perform end-to-end integration testing across all implemented features. Ensure compatibility, fix defects, and verify that combined changes work together.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-010",
      "activity_name": "Documentation and release preparation",
      "activity_description": "Write or update documentation for all new features. Prepare release notes, update API docs, and ensure configuration reference is complete.",
      "most_likely_effort": 20
    }
  ],
  "reported_total": {
    "most_likely_effort": 353
  }
}

